package com.odyssey.travelplanner.ui

import java.util.Locale

// Keep the same topics, actions and example rows in every language.
private data class ExplainedCopy(val title: String, val why: String, val action: String, val result: String)

internal fun explainedTopicsForLanguage(language: String): List<ExplainedTopic> {
    val locale = language.trim().uppercase(Locale.ROOT).substringBefore('-')
    val index = when (locale) { "EN" -> 0; "ES" -> 1; "DE" -> 2; else -> return explainedTopics }
    val copies = when (locale) { "EN" -> englishExplainedCopy; "ES" -> spanishExplainedCopy; else -> germanExplainedCopy }
    var stepIndex = 0
    fun example(value: String): String = explainedExamples.getValue(value)[index]
    return explainedTopics.map { topic ->
        topic.copy(name = example(topic.name), steps = topic.steps.map { step ->
            val copy = copies[stepIndex++]
            step.copy(title = copy.title, why = copy.why, action = copy.action, result = copy.result,
                exampleTitle = example(step.exampleTitle), exampleRows = step.exampleRows.map(::example))
        })
    }
}

